CREATE TABLE IF NOT EXISTS plans(code varchar(30) PRIMARY KEY,name varchar(80) NOT NULL,price_cents integer NOT NULL,barber_limit integer NOT NULL,monthly_appointment_limit integer NOT NULL,whatsapp_limit integer NOT NULL,active boolean NOT NULL DEFAULT true);
INSERT INTO plans(code,name,price_cents,barber_limit,monthly_appointment_limit,whatsapp_limit) VALUES('STARTER','Essencial',7900,3,300,0),('PRO','Profissional',14900,10,2000,1000),('SCALE','Escala',29900,50,10000,5000) ON CONFLICT(code) DO NOTHING;
CREATE TABLE IF NOT EXISTS subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL UNIQUE REFERENCES organizations(id) ON DELETE CASCADE,plan_code varchar(30) NOT NULL REFERENCES plans(code),status varchar(20) NOT NULL DEFAULT 'TRIAL',current_period_start timestamptz NOT NULL DEFAULT now(),current_period_end timestamptz NOT NULL DEFAULT now()+interval '14 days',provider varchar(30),provider_customer_id text,provider_subscription_id text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO subscriptions(organization_id,plan_code,status,current_period_end) SELECT id,plan,CASE WHEN status='TRIAL' THEN 'TRIAL' ELSE 'ACTIVE' END,COALESCE(trial_ends_at,now()+interval '1 month') FROM organizations ON CONFLICT(organization_id) DO NOTHING;
